<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
type Recipient = Record<string, string | number>
type Template = { _id?: string; name: string; title: string; type: string; primaryField: string; body: string; signatory: string; organization: string; accent: string; logo?: string }
const template = ref<Template>({ name: 'Sertifikat Penyelesaian Kelas', title: 'Certificate of Achievement', type: 'PENGHARGAAN', primaryField: 'nama', body: 'telah menyelesaikan {{kelas}} dengan hasil yang membanggakan pada {{tanggal}}.', signatory: 'Dewi Anggraini', organization: 'AKADEMI NUSANTARA', accent: '#0f766e', logo: '' })
const recipients = ref<Recipient[]>([{ nama: 'Nadia Pratama', kelas: 'Kelas Desain Produk', tanggal: '14 September 2026' }, { nama: 'Raka Wijaya', kelas: 'Kelas Desain Produk', tanggal: '14 September 2026' }])
const headers = ref(['nama', 'kelas', 'tanggal']), selectedIndex = ref(0), status = ref('Siap digunakan'), connection = ref<'connecting' | 'connected' | 'offline'>('connecting'), savedTemplates = ref<Template[]>([]), fileInput = ref<HTMLInputElement>(), logoInput = ref<HTMLInputElement>()
const selected = computed(() => recipients.value[selectedIndex.value] ?? {})
const displayName = computed(() => String(selected.value[template.value.primaryField] || 'Nama Penerima'))
const previewBody = computed(() => template.value.body.replace(/{{\s*([^}]+)\s*}}/g, (_, key) => String(selected.value[key.trim()] ?? `{{${key.trim()}}}`)))
const placeholders = computed(() => headers.value.map((name) => `{{${name}}}`))
async function importExcel(event: Event) { const file = (event.target as HTMLInputElement).files?.[0]; if (!file) return; status.value = 'Membaca file Excel…'; const form = new FormData(); form.append('file', file); const response = await fetch('/api/import', { method: 'POST', body: form }); const data = await response.json(); if (!response.ok) { status.value = data.message; return }; headers.value = data.headers; recipients.value = data.rows; selectedIndex.value = 0; if (!headers.value.includes(template.value.primaryField)) template.value.primaryField = headers.value[0] || ''; status.value = `${data.rows.length} penerima berhasil diimpor` }
function uploadLogo(event: Event) { const file = (event.target as HTMLInputElement).files?.[0]; if (!file) return; if (!file.type.startsWith('image/')) { status.value = 'Logo harus berupa file gambar.'; return }; if (file.size > 3 * 1024 * 1024) { status.value = 'Ukuran logo maksimal 3 MB.'; return }; const reader = new FileReader(); reader.onload = () => { template.value.logo = String(reader.result); status.value = 'Logo siap disimpan sebagai Base64' }; reader.readAsDataURL(file) }
function removeLogo() { template.value.logo = ''; if (logoInput.value) logoInput.value.value = ''; status.value = 'Logo dihapus dari template' }
async function checkConnection() { try { const response = await fetch('/api/health'); connection.value = (await response.json()).database; if (connection.value === 'connected') loadTemplates() } catch { connection.value = 'offline' } }
async function loadTemplates() { const response = await fetch('/api/templates'); if (response.ok) savedTemplates.value = await response.json() }
async function saveTemplate() { if (connection.value !== 'connected') { status.value = 'MongoDB belum tersambung. Template masih dapat digunakan untuk ekspor.'; return }; const response = await fetch('/api/templates', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(template.value) }); if (!response.ok) { status.value = (await response.json()).message; return }; status.value = 'Template tersimpan di MongoDB Atlas'; loadTemplates() }
function useTemplate(item: Template) { template.value = { ...item }; status.value = 'Template dimuat' }
async function exportPDF() { if (!recipients.value.length) { status.value = 'Impor data penerima terlebih dahulu.'; return }; status.value = 'Menyiapkan PDF…'; const response = await fetch('/api/certificates/pdf', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ template: template.value, recipient: selected.value }) }); if (!response.ok) { status.value = (await response.json()).message; return }; const url = URL.createObjectURL(await response.blob()); const a = document.createElement('a'); a.href = url; a.download = `sertifikat-${displayName.value}.pdf`; a.click(); URL.revokeObjectURL(url); status.value = 'PDF berhasil diunduh' }
onMounted(checkConnection)
</script>
<template>
  <main class="app-shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">✦</span><span>certify</span></div><nav><a class="active">Buat sertifikat</a><a>Template tersimpan <b>{{ savedTemplates.length }}</b></a></nav><div class="side-bottom"><span class="dot" :class="connection"></span><span>{{ connection === 'connected' ? 'MongoDB Atlas terhubung' : connection === 'connecting' ? 'Menghubungkan database…' : 'Mode offline' }}</span></div></aside>
    <section class="workspace"><header class="topbar"><div><p class="eyebrow">SERTIFIKAT GENERATOR</p><h1>Buat sertifikat yang terasa personal.</h1></div><button class="outline" @click="saveTemplate">Simpan template</button></header><p class="status">{{ status }}</p>
      <div class="content-grid"><section class="editor-card"><div class="section-title"><span class="step">01</span><div><h2>Desain & isi</h2><p>Atur teks yang akan digunakan untuk setiap penerima.</p></div></div><label>Nama template<input v-model="template.name" /></label><div class="two-cols"><label>Judul sertifikat<input v-model="template.title" /></label><label>Jenis<span class="select-wrap"><select v-model="template.type"><option>APRESIASI</option><option>PENGHARGAAN</option><option>KELULUSAN</option><option>PARTISIPASI</option></select></span></label></div><div class="two-cols"><label>Organisasi<input v-model="template.organization" /></label><label>Penandatangan<input v-model="template.signatory" /></label></div><label>Kolom nama penerima<span class="select-wrap"><select v-model="template.primaryField"><option v-for="header in headers" :key="header">{{ header }}</option></select></span></label><label>Isi penghargaan<textarea v-model="template.body" rows="3" /></label><div class="tokens"><span>Masukkan kolom Excel:</span><button v-for="token in placeholders" :key="token" @click="template.body += ` ${token}`">{{ token }}</button></div><div class="logo-field"><div><span>Logo organisasi</span><small>PNG, JPG, atau WebP, maks. 3 MB.</small></div><button class="upload" @click="logoInput?.click()">{{ template.logo ? 'Ganti logo' : 'Unggah logo' }}</button><input ref="logoInput" hidden type="file" accept="image/png,image/jpeg,image/webp" @change="uploadLogo" /><button v-if="template.logo" class="remove-logo" @click="removeLogo">Hapus</button></div><label class="color-field">Warna utama<input v-model="template.accent" type="color" /><code>{{ template.accent }}</code></label></section>
        <section class="preview-area"><div class="section-title"><span class="step">PREVIEW</span><div><h2>Hasil sertifikat</h2><p>Pratinjau dari data penerima aktif.</p></div></div><article class="certificate" :style="{ '--accent': template.accent }"><div class="inner"><img v-if="template.logo" class="certificate-logo" :src="template.logo" alt="Logo organisasi" /><p class="org">{{ template.organization }}</p><h3>{{ template.title }}</h3><p class="cert-type">SERTIFIKAT {{ template.type }}</p><p class="awarded">Dengan bangga diberikan kepada</p><p class="recipient">{{ displayName }}</p><div class="rule"></div><p class="body-copy">{{ previewBody }}</p><div class="signature"><span>Ditetapkan dengan penuh penghargaan</span><strong>{{ template.signatory }}</strong><small>{{ template.organization }}</small></div></div></article><button class="primary full" @click="exportPDF">Unduh PDF untuk {{ displayName }} <span>→</span></button></section></div>
      <section class="data-card"><div class="section-title"><span class="step">02</span><div><h2>Data penerima</h2><p>Excel bisa memiliki kolom apa pun. Gunakan nama kolom sebagai placeholder di atas.</p></div><button class="upload" @click="fileInput?.click()">↑ Impor Excel</button><input ref="fileInput" hidden type="file" accept=".xlsx,.xls" @change="importExcel" /></div><div v-if="recipients.length" class="table-wrap"><table><thead><tr><th>#</th><th v-for="header in headers" :key="header">{{ header }}</th><th></th></tr></thead><tbody><tr v-for="(row, index) in recipients" :key="index" :class="{ chosen: selectedIndex === index }"><td>{{ String(index + 1).padStart(2, '0') }}</td><td v-for="header in headers" :key="header">{{ row[header] }}</td><td><button class="select" @click="selectedIndex = index">{{ selectedIndex === index ? 'Dipilih' : 'Pilih' }}</button></td></tr></tbody></table></div><div v-else class="empty">Belum ada data. Impor file Excel dengan baris pertama sebagai header.</div></section>
      <section v-if="savedTemplates.length" class="saved"><h2>Template tersimpan</h2><button v-for="item in savedTemplates" :key="item._id" @click="useTemplate(item)">{{ item.name }} <span>↗</span></button></section></section></main>
</template>
<style>
@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:ital,wght@0,600;0,700;1,600&display=swap');
*{box-sizing:border-box}body{margin:0;background:#f6f5f0;color:#1b292b;font-family:'DM Sans',sans-serif}.app-shell{min-height:100vh;display:flex}.sidebar{width:235px;background:#153538;color:#e8f2ed;padding:32px 20px;display:flex;flex-direction:column;position:fixed;inset:0 auto 0 0}.brand{display:flex;align-items:center;gap:10px;font-family:'Playfair Display';font-size:28px;font-weight:700;padding:0 10px}.brand-mark{display:grid;place-items:center;background:#d4e9a2;color:#153538;width:28px;height:28px;border-radius:9px;font-family:serif;font-size:18px}nav{margin-top:72px;display:grid;gap:7px}nav a{padding:12px 14px;border-radius:9px;color:#b9cfcb;font-size:14px;display:flex;justify-content:space-between}nav .active{background:#244a4c;color:#fff;font-weight:600}.side-bottom{font-size:12px;color:#9cb9b4;margin-top:auto;display:flex;gap:8px;align-items:center;padding:9px}.dot{width:8px;height:8px;background:#d4a538;border-radius:50%}.dot.connected{background:#a9d477}.dot.offline{background:#df8979}.workspace{padding:42px 52px 70px;margin-left:235px;width:calc(100% - 235px);max-width:1600px}.topbar{display:flex;justify-content:space-between;align-items:flex-start}.eyebrow{font-family:'DM Mono';font-size:11px;color:#71817d;letter-spacing:1.2px;margin:0 0 8px}h1{font-family:'Playfair Display';font-size:36px;margin:0;letter-spacing:-.8px}h2{font-size:16px;margin:0 0 4px}p{margin:0}.status{font-size:13px;color:#71817d;margin:13px 0 24px}.outline,.upload,.select,.remove-logo{border:1px solid #b9c6c1;background:transparent;color:#234447;border-radius:7px;padding:10px 14px;font:600 13px 'DM Sans';cursor:pointer}.content-grid{display:grid;grid-template-columns:minmax(400px,1fr) minmax(420px,1.05fr);gap:24px}.editor-card,.data-card{background:#fff;border:1px solid #e1e5df;border-radius:14px;padding:26px;box-shadow:0 6px 22px #19332d08}.section-title{display:flex;align-items:flex-start;gap:11px;margin-bottom:22px}.section-title p{font-size:13px;color:#768480}.step{font:500 10px 'DM Mono';color:#48736e;border:1px solid #b9cec7;background:#edf5ef;padding:6px 7px;border-radius:5px;margin-top:1px}.editor-card label{display:block;font-size:12px;font-weight:600;color:#52615d;margin:15px 0 0}.editor-card input:not([type=color]),textarea,select{font:400 14px 'DM Sans';color:#1b292b;width:100%;border:1px solid #d5ded9;border-radius:7px;background:#fcfdfb;padding:10px;margin-top:7px;outline-color:#5c928a}textarea{resize:vertical;line-height:1.45}.two-cols{display:grid;grid-template-columns:1fr 1fr;gap:14px}.select-wrap{display:block;position:relative}.select-wrap:after{content:'⌄';position:absolute;right:12px;bottom:8px;color:#62716d;pointer-events:none}select{appearance:none}.tokens{display:flex;gap:7px;align-items:center;flex-wrap:wrap;margin-top:11px;font-size:11px;color:#7b8985}.tokens button{border:0;border-radius:4px;background:#e8f1ed;color:#37655f;padding:4px 6px;font:11px 'DM Mono';cursor:pointer}.logo-field{border:1px dashed #bfd1c8;background:#f7faf7;border-radius:8px;padding:10px 11px;margin-top:16px;display:flex;align-items:center;gap:9px}.logo-field div{margin-right:auto;display:grid;gap:2px;font-size:12px;font-weight:600;color:#52615d}.logo-field small{font-size:10px;font-weight:400;color:#7b8985}.logo-field .upload,.logo-field .remove-logo{padding:7px 9px;font-size:11px}.remove-logo{color:#9c3d3a;border-color:#e2b7b3}.color-field{display:flex!important;align-items:center;gap:10px}.color-field input{width:28px;height:28px;padding:2px;border:1px solid #d5ded9;border-radius:5px;margin:0 0 0 4px}.color-field code{font:12px 'DM Mono';color:#73817e}.preview-area{min-width:0}.certificate{background:#faf9f4;padding:11px;border:3px solid var(--accent);box-shadow:0 10px 25px #1b3d3120;aspect-ratio:1.414;margin-bottom:18px}.inner{height:100%;border:1px solid #ddcd94;text-align:center;padding:8.5% 9%;position:relative}.certificate-logo{position:absolute;top:8%;left:7%;width:48px;height:48px;object-fit:contain}.org{font:600 10px 'DM Mono';letter-spacing:1.6px;color:var(--accent);margin-bottom:22px}.certificate h3{font:700 clamp(24px,3.1vw,39px) 'Playfair Display';color:#1b292b;margin:0}.cert-type{font:10px 'DM Mono';letter-spacing:2px;color:#84908e;margin-top:10px}.awarded{font-size:12px;color:#596763;margin-top:33px}.recipient{font:600 italic clamp(23px,3.2vw,38px) 'Playfair Display';color:var(--accent);margin:8px 0}.rule{height:1px;background:#dccd92;width:44%;margin:0 auto 20px}.body-copy{font-size:12px;line-height:1.5;color:#44504d;max-width:480px;margin:auto}.signature{position:absolute;right:11%;bottom:11%;display:grid;gap:4px;text-align:center;color:#5c6865;font-size:10px}.signature strong{font:600 17px 'Playfair Display';color:#1b292b}.signature small{font:10px 'DM Mono';color:#768480}.primary{background:#1e5a55;color:#fff;border:0;border-radius:7px;padding:13px 16px;font:600 14px 'DM Sans';cursor:pointer}.primary span{margin-left:12px;font-size:18px}.full{width:100%}.data-card{margin-top:25px}.data-card .section-title{margin-bottom:14px}.upload{margin-left:auto}.table-wrap{overflow:auto;border:1px solid #e4e9e5;border-radius:8px}table{border-collapse:collapse;width:100%;font-size:13px;white-space:nowrap}th{text-align:left;background:#f3f6f3;color:#72807d;font:500 10px 'DM Mono';letter-spacing:.6px;text-transform:uppercase}th,td{padding:13px 14px;border-bottom:1px solid #e8ece8}tbody tr:last-child td{border:0}td:first-child{font:11px 'DM Mono';color:#87938f}.chosen{background:#f1f8f3}.select{padding:6px 10px;font-size:12px}.chosen .select{border-color:#7bac87;color:#246144;background:#f5fbf4}.empty{padding:28px;border:1px dashed #cbd6d0;color:#74817d;text-align:center;border-radius:8px;font-size:13px}.saved{margin-top:23px;display:flex;align-items:center;gap:10px;flex-wrap:wrap}.saved h2{margin-right:8px}.saved button{border:1px solid #d9e2dc;background:#fff;border-radius:100px;padding:8px 12px;color:#315854;font:500 12px 'DM Sans';cursor:pointer}.saved button span{margin-left:6px}@media(max-width:980px){.sidebar{width:70px;padding:26px 10px}.brand span:last-child,nav a:not(.active),.side-bottom span:last-child{display:none}.brand{padding:0;justify-content:center}.workspace{margin-left:70px;width:calc(100% - 70px);padding:32px}.content-grid{grid-template-columns:1fr}}@media(max-width:620px){.sidebar{display:none}.workspace{margin:0;width:100%;padding:23px 16px}.topbar{gap:14px}.topbar h1{font-size:29px}.outline{white-space:nowrap}.content-grid,.two-cols{grid-template-columns:1fr}.certificate{margin-top:10px}.upload{margin-left:0}.data-card .section-title{flex-wrap:wrap}.logo-field{flex-wrap:wrap}.logo-field div{width:100%}}
</style>
